/** CannaCon preview builder. Node.js 20+; no dependencies, secrets, or network calls.
 *  Edit content/site.json, then run: node cannacon/build.mjs
 *  Only this cannacon directory is written. Existing Play At Scale files are untouched.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const ROOT=path.dirname(fileURLToPath(import.meta.url));
const D=JSON.parse(fs.readFileSync(path.join(ROOT,'content/site.json'),'utf8'));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const price=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const date=v=>v?new Date(v+'T12:00:00Z').toLocaleDateString('en-US',{month:'long',day:'numeric',timeZone:'UTC'}):'To be announced';
const external=u=>/^https?:\/\//.test(u);
const arrow='<span aria-hidden="true">&#8599;</span>';
let B='';
const url=p=>external(p)||p.startsWith('mailto:')||p.startsWith('#')?p:B+p;
const link=(p,t,cls='text-link',extras='')=>`<a href="${esc(url(p))}" class="${cls}" ${external(p)?'target="_blank" rel="noopener noreferrer"':''} ${extras}>${t}</a>`;
const img=(src,alt,cls='',priority=false)=>`<img class="${cls}" src="${esc(url(src))}" alt="${esc(alt)}" width="1200" height="800" ${priority?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const logo=()=>`<img src="${B}assets/brand/cannacon-wordmark.png" alt="CannaCon" width="1632" height="378">`;
const sectionHead=(eye,title,copy='',action='')=>`<div class="section-heading"><div><p class="eyebrow">${eye}</p><h2>${title}</h2>${copy?`<p class="section-intro">${copy}</p>`:''}</div>${action}</div>`;
const pageHead=(eye,title,copy,buttons='')=>`<section class="page-hero"><div class="wrap"><p class="eyebrow">${eye}</p><h1>${title}</h1><p class="lead">${copy}</p>${buttons?`<div class="button-row">${buttons}</div>`:''}</div><div class="hero-hand" aria-hidden="true"></div></section>`;
function eventCards(){return `<div class="event-grid">${D.events.map(e=>`<article class="event-card"><div class="media-frame">${img(D.media[e.image],'Photography from previous CannaCon events')}<span class="image-label">2027 / ${esc(e.region)}</span></div><div class="event-card-content"><p class="eyebrow">CannaCon presents</p><h3>${esc(e.city)}<span>${esc(e.state)}</span></h3><p class="event-date">${esc(e.datesLabel)}</p><p class="muted">${esc(e.venue)}</p><p class="event-extra">${e.preDate?`${esc(e.preLabel)}: financial course + pre-show networking`:'Exact dates and Vegas programming to be confirmed.'}</p><div class="button-row">${link('exhibit.html?show='+e.code+'#inquire','Exhibit '+arrow,'button button-dark')}${link(e.code+'/','Explore show','button button-quiet')}</div><div class="utility-links">${link(e.floorPlan,'Floor plan '+arrow)}${link(e.code+'/#tickets','Pass options')}${link(e.code+'/#program','Program')}</div></div></article>`).join('')}</div>`;}
function pavilions(){return `<div class="pavilion-grid">${D.pavilions.map((p,i)=>`<article class="pavilion-card"><div class="pavilion-photo">${img(D.media[p.image],'Previous CannaCon show-floor photography')}</div><div class="pavilion-copy"><span class="index-no">0${i+1}</span><p class="eyebrow">${esc(p.eyebrow)}</p><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><p class="small">${esc(p.detail)}</p>${link('exhibit.html#inquire','Find your place '+arrow,'text-link light')}</div></article>`).join('')}</div>`;}
function articles(all=false){return `<div class="article-grid ${all?'all-articles':''}">${D.articles.slice(0,all?4:3).map(a=>`<article class="article-card"><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer" class="article-photo" tabindex="-1" aria-hidden="true">${img(a.image,'')}</a><div class="article-copy"><div class="meta"><span>${esc(a.category)}</span><time datetime="${esc(a.date)}">${esc(new Date(a.date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}))}</time></div><h3>${link(a.url,esc(a.title),'article-title')}</h3><p>${esc(a.excerpt)}</p>${link(a.url,'Read on CannaCon.org '+arrow)}</div></article>`).join('')}</div>`;}
function newsletter(){return `<section class="newsletter"><div class="wrap newsletter-grid"><div><p class="eyebrow">Beyond the show floor</p><h2>Stay in the conversation.</h2><p>Show announcements, industry stories and the people moving cannabis forward.</p></div><form data-newsletter class="newsletter-form"><label for="newsletter-email">Email address</label><div class="input-row"><input id="newsletter-email" name="email" type="email" autocomplete="email" placeholder="you@company.com" required><button type="submit" class="button button-dark">Preview signup</button></div><p class="small">Prototype only. No email is stored or submitted. Constant Contact connection is pending.</p><p class="form-status" data-newsletter-status role="status"></p></form></div></section>`;}
function decks(which=[0,1]){return `<div class="deck-grid">${which.map(i=>D.decks[i]).map(d=>`<article class="deck-card"><div class="deck-cover">${img(d.cover,d.label+' cover')}</div><div><p class="eyebrow">PDF / opens in a new tab</p><h3>${esc(d.title)}</h3><p class="small">${esc(d.note)}</p>${link(d.file,'View '+esc(d.label)+' '+arrow,'button button-dark','target="_blank" rel="noopener" type="application/pdf"')}</div></article>`).join('')}</div>`;}
// Accessible native inquiry forms. No hosted-form API, iframe, or email server.
// A browser mail client sends the message only when the visitor chooses to send it.
function nativeField(key, spec) {
  const {name,label,type='text',options=[],required=false,help='',condition=''}=spec;
  const id=`${key}-${name}`;
  const hint=help?`<small id="${id}-help">${esc(help)}</small>`:'';
  const common=`name="${name}" id="${id}" data-label="${esc(label)}" ${required?'required':''} ${help?`aria-describedby="${id}-help"`:''}`;
  const cond=condition?`data-show-when="${esc(condition)}" hidden`:'';
  if(type==='checks') return `<fieldset class="native-checks full" ${cond}><legend>${esc(label)}${required?' *':''}</legend>${options.map((o,i)=>`<label><input type="checkbox" name="${name}" value="${esc(o)}" data-label="${esc(label)}" id="${id}-${i}"><span>${esc(o)}</span></label>`).join('')}${hint}</fieldset>`;
  let control;
  if(type==='textarea') control=`<textarea ${common} rows="${name==='message'?5:3}" maxlength="2500"></textarea>`;
  else if(type==='select') control=`<select ${common}><option value="">Please select</option>${options.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select>`;
  else control=`<input ${common} type="${type}" maxlength="${type==='url'?600:180}" ${type==='email'?'autocomplete="email"':name==='fullName'?'autocomplete="name"':name==='company'?'autocomplete="organization"':type==='tel'?'autocomplete="tel"':''}>`;
  return `<div class="native-field ${type==='textarea'?'full':''}" ${cond}><label for="${id}">${esc(label)}${required?' <span aria-hidden="true">*</span>':''}</label>${control}${hint}</div>`;
}
function formBlock(key){
  const f=D.forms[key];
  const companyTypes=['Brand / Manufacturer','Cultivator / Hemp producer','Processor / Extractor','Retail / Dispensary','Distributor / Wholesaler','Equipment / Packaging / Ingredients','Culture / Glass / Accessories','Technology / Professional services','Other'];
  const pavilion=['Infused Product Expo','The Culture Pavilion','Cannabis Commerce Pavilion','Education / Programming','Not sure yet'];
  const fields=[
    {name:'fullName',label:'Full name',required:true},
    {name:'email',label:'Email address',type:'email',required:true},
    {name:'company',label:'Company / organization',required:true},
    {name:'role',label:'Job title / role'},
    {name:'website',label:'Company website',type:'url',help:'Optional. Include https://.'},
    {name:'phone',label:'Phone',type:'tel'},
    {name:'inquiryType',label:'Inquiry type',type:'select',options:f.inquiryTypes,required:true},
    {name:'otherInquiry',label:'Please describe your inquiry',condition:'inquiryType=Other',required:true},
    {name:'show',label:'Show location / dates',type:'select',required:true,options:D.events.map(e=>`${e.name} | ${e.preDate?date(e.preDate)+' pre-show; ':''}${e.datesLabel}` ).concat(['Multiple shows','Other / Not sure'])},
    {name:'showNotes',label:'Other show or location of interest',condition:'show=Other / Not sure',required:true}
  ];
  if(key==='exhibitor')fields.push(
    {name:'businessType',label:'Business / product category',type:'select',options:companyTypes,required:true},
    {name:'categoryOther',label:'Please describe your business category',condition:'businessType=Other',required:true},
    {name:'pavilion',label:'Pavilion of interest',type:'select',options:pavilion},
    {name:'boothSize',label:'Space requirements',type:'select',options:['10 x 10 ft','10 x 20 ft','20 x 20 ft','Larger / custom footprint','Not sure - please advise']},
    {name:'budget',label:'Indicative budget',type:'select',options:['Under $5,000','$5,000-$10,000','$10,000-$25,000','$25,000+','Not determined / Prefer not to say']},
    {name:'past',label:'Previous CannaCon participation',type:'select',options:['First-time exhibitor','Previously exhibited','Previously attended','Other']},
    {name:'brandDeck',label:'Public brand-deck link',type:'url'},
    {name:'referral',label:'How did you hear about CannaCon?'},
    {name:'message',label:'What would you like to accomplish?',type:'textarea',required:true,help:'Products, target buyers, demonstration needs, timing or specific questions.'}
  );
  if(key==='speaker')fields.push(
    {name:'title',label:'Proposed session title',required:true},
    {name:'topic',label:'Topic',type:'select',options:['Cultivation / Hemp','Infused products','Commerce / Retail','Finance / Operations','Technology','Culture / Art / Community','Other'],required:true},
    {name:'topicOther',label:'Please describe the topic',condition:'topic=Other',required:true},
    {name:'audience',label:'Who is this session for?',required:true},
    {name:'format',label:'Preferred format',type:'select',options:['Presentation','Panel','Workshop','Demonstration','Other / Discuss with team']},
    {name:'bio',label:'Short speaker bio',type:'textarea',required:true},
    {name:'abstract',label:'Session abstract',type:'textarea',required:true},
    {name:'outcomes',label:'Three practical learning outcomes',type:'textarea',required:true},
    {name:'video',label:'Past presentation / video URL',type:'url'},
    {name:'headshot',label:'Headshot URL',type:'url'},
    {name:'notes',label:'Co-presenters, availability and commercial affiliations',type:'textarea'}
  );
  if(key==='sponsor')fields.push(
    {name:'pavilion',label:'Preferred pavilion / program',type:'select',options:pavilion},
    {name:'budget',label:'Indicative budget',type:'select',options:['Under $5,000','$5,000-$15,000','$15,000-$30,000','$30,000+','Not determined / Prefer not to say']},
    {name:'audience',label:'Audience you want to reach',required:true},
    {name:'timing',label:'Decision timeline'},
    {name:'deck',label:'Public company / brand-deck URL',type:'url'},
    {name:'message',label:'Partnership goals and proposed activation',type:'textarea',required:true},
    {name:'deliverables',label:'Requested benefits or deliverables',type:'textarea'},
    {name:'history',label:'Existing CannaCon relationship',type:'textarea'}
  );
  if(key==='buyer')fields.push(
    {name:'businessType',label:'Buyer / business type',type:'select',required:true,options:['Retail / Dispensary','Distributor / Wholesaler','Convenience / Specialty retail','MSO / Multi-location team','Beverage / Category manager','Purchasing executive','Supply-chain buyer','Other']},
    {name:'businessOther',label:'Please describe your buyer type',condition:'businessType=Other',required:true},
    {name:'authority',label:'Purchasing role',type:'select',required:true,options:['Final purchasing authority','Shared purchasing authority','Recommender / Evaluator','Researching for a team','Other']},
    {name:'stores',label:'Number of locations / stores'},
    {name:'markets',label:'Geographic markets served',required:true},
    {name:'volume',label:'Indicative annual purchasing volume',type:'select',options:['Under $100,000','$100,000-$500,000','$500,000-$2 million','$2 million+','Prefer not to say']},
    {name:'categories',label:'Categories of interest',type:'checks',options:['Gummies / Chews','Chocolates / Confections','Baked goods / Snacks','Beverages','Vapes / Cartridges','Concentrates','Flower / Pre-rolls','Capsules / Softgels','Tinctures / Oils','Topicals','Mushroom-infused products','Hemp-derived products','Functional wellness','Pet products','Personal care / Beauty','Ingredients / Equipment / Packaging','Other'],help:'Interest categories only. Product availability and permitted activities depend on event rules.'},
    {name:'priorities',label:'What are you looking to source?',type:'textarea',required:true},
    {name:'introductions',label:'Specific suppliers or introductions requested',type:'textarea'},
    {name:'requirements',label:'Product requirements / certifications',type:'textarea'},
    {name:'timeline',label:'Buying timeline / meeting availability'},
    {name:'notes',label:'Other categories or additional information',type:'textarea'}
  );
  const notice=key==='buyer'?'Eligibility, introductions and hosted benefits are subject to review. No admission, meetings, travel or accommodation is guaranteed.':key==='speaker'?'Proposals are reviewed individually. Acceptance, compensation, travel support and scheduling are not guaranteed; terms would be agreed separately.':'Availability, pricing and any sponsorship benefits will be confirmed by the CannaCon team.';
  return `<section class="section" id="inquire"><div class="wrap form-layout"><div><p class="eyebrow">Start the conversation</p><h2>${esc(f.title)}</h2><p>Tell us which show interests you and what you want to accomplish.</p><div class="notice"><strong>Email-draft workflow</strong><p>This page does not submit or store your inquiry. Prepare the message, then send it from your email app to ${esc(D.brand.contactEmail)}. Copy and save options are available.</p></div><p class="small">${esc(notice)}</p>${link('mailto:'+D.brand.contactEmail+'?subject='+encodeURIComponent(f.subject),'Email the team directly '+arrow)}</div><div class="form-mount"><form data-email-form="${key}" class="native-inquiry" autocomplete="on"><p class="small">Fields marked * are required. No attachments or payments are collected.</p><div class="native-field-grid">${fields.map(field=>nativeField(key,field)).join('')}</div><label class="consent-line"><input type="checkbox" name="contactConsent" value="Yes" data-label="Consent to contact about this inquiry" required><span>I agree to be contacted about this inquiry. *</span></label><label class="consent-line"><input type="checkbox" name="newsletterInterest" value="Interested - request only, not a subscription" data-label="Newsletter interest"><span>I am interested in the CannaCon newsletter. Optional; this does not subscribe me.</span></label><button class="button button-orange" type="submit">Prepare email draft ${arrow}</button><p class="small">Nothing is sent until you send the email. Your input is not saved after leaving this page.</p><div class="email-preview" data-email-preview hidden tabindex="-1"><h3>Your email is ready to review.</h3><p>To: <strong>${esc(D.brand.contactEmail)}</strong><br>Subject: <strong>${esc(f.subject)}</strong></p><label for="${key}-email-text">Message text</label><textarea id="${key}-email-text" data-email-text readonly rows="10"></textarea><p class="form-status" data-email-status role="status"></p><div class="button-row"><a class="button button-dark" data-open-email href="mailto:${esc(D.brand.contactEmail)}">Open email draft ${arrow}</a><button class="button button-quiet" type="button" data-copy-email>Copy message</button><button class="plain-button" type="button" data-save-email>Save as text</button></div><p class="small">Webmail users: copy the message into Gmail or your usual email service. This page cannot confirm delivery.</p></div></form></div></div></section>`;
}

function cta(){return `<section class="closing"><div class="wrap"><p class="eyebrow">Be part of what comes next</p><h2>${esc(D.brand.rallyingLine)}</h2><div class="button-row">${link('exhibit.html#inquire','Exhibit at CannaCon '+arrow,'button button-orange')}${link('events.html','Find your show','button button-outline')}</div></div></section>`;}
function story(){return `<div class="story-grid"><div><p class="eyebrow">Built on experience</p><h2>${esc(D.history.heading)}</h2><p>${esc(D.history.text)}</p>${link('about.html','Meet the CannaCon story '+arrow)}</div><div class="experience-stats">${D.history.metrics.map(m=>`<div><strong>${esc(m.value)}</strong><span>${esc(m.label)}</span></div>`).join('')}<p class="small">${esc(D.history.attribution)}</p></div></div>`;}
function sponsors(){return `<section class="section soft"><div class="wrap">${sectionHead('The community around the show','More connections. More possibility.','Our 2027 sponsor and partner showcase is being assembled. Confirmed organizations will appear here.',link('sponsor.html','Explore sponsorship '+arrow))}${D.sponsors.length?`<div class="sponsor-grid">${D.sponsors.map(s=>{const w=D.sponsorDisplay.tierWeights[s.tier]||1;const max=Math.max(...Object.values(D.sponsorDisplay.tierWeights));const width=D.sponsorDisplay.minWidth+(D.sponsorDisplay.maxWidth-D.sponsorDisplay.minWidth)*Math.log1p(w)/Math.log1p(max);return `<a href="${esc(s.url)}" class="sponsor-logo" style="--logo-width:${Math.round(width)}px">${img(s.logo,s.name)}</a>`}).join('')}</div>`:`<div class="partner-placeholder"><span>PARTNER SHOWCASE</span><p>Reserved for confirmed partners.<br>No affiliations are implied.</p><span aria-hidden="true">&#8599;</span></div>`}</div></section>`;}
function videoBlock(){return `<section class="section dark"><div class="wrap">${sectionHead('Experience CannaCon','Real people. Real conversations.','A look back at the energy of CannaCon. Archival footage, not a representation of the 2027 floor.')}<div class="video-poster" data-video-mount>${img(D.media.conversations,'CannaCon attendees talking on the show floor')}<div class="video-shade"></div><button type="button" class="play-button" data-play-youtube aria-label="Load and play CannaCon video on YouTube"><span aria-hidden="true">&#9654;</span><span>Watch the CannaCon experience</span></button></div><p class="small">Playing loads YouTube, a third-party service. ${link(D.socials.youtube,'Explore our YouTube channel '+arrow,'text-link light')}</p></div></section>`;}
function program(e, anchor="program"){return `<section class="section soft" id="${esc(anchor)}"><div class="wrap">${sectionHead('Plan your time','The show. And everything around it.','All published times are local to the venue. Specific seminar, culture and networking schedules will follow.')}<div class="program-grid">${e.preDate?`<article class="program-card"><p class="eyebrow">Pre-show / ${esc(e.preLabel)}</p><h3>Learn. Meet. Get ready.</h3><p>Financial course Session 1, plus pre-show and exhibitor networking events.</p><p class="small">Course: 3 hours; time to be announced. Course admission is separate from the all-access pass.</p></article>`:''}${e.days.map((d,i)=>`<article class="program-card"><p class="eyebrow">Expo day ${i+1} / ${esc(d.label)}</p><h3>${esc(d.hours)}</h3><p>Explore the pavilions, general seminars and culture programming.</p><p class="small">Financial course Session ${i+2}: 3 hours, separately ticketed. Time to be announced.</p></article>`).join('')}${!e.days.length?'<article class="program-card"><p class="eyebrow">Vegas planning</p><h3>May 2027</h3><p>Exact expo dates, hours and the Vegas education format are being confirmed. The three-day regional format has not been applied to this show.</p></article>':''}</div></div></section>`;}
function tickets(e){const standard=e.preDate?D.tickets:D.tickets.filter(t=>t.id!=='all');return `<section class="section" id="tickets"><div class="wrap">${sectionHead('Choose your experience','Passes & practical education.','Preview the options below. Checkout is not connected, and this page cannot issue tickets or accept payment.')}<div class="ticket-layout" data-ticket-builder="${e.code}"><div><fieldset class="ticket-fieldset"><legend>Expo admission <span>General seminars included</span></legend><label class="no-pass"><input type="radio" name="expo-pass" value="none" checked> No expo pass selected</label><div class="ticket-grid">${standard.map(t=>`<label class="ticket-card"><input type="radio" name="expo-pass" value="${t.id}"><span class="ticket-title">${esc(t.name)}</span><strong>${price(t.price)}</strong><span>${esc(t.description)}</span><small>${esc(t.includes)}</small></label>`).join('')}</div><div class="day-picker" data-day-picker hidden><label for="visit-day">Choose your expo day</label><select id="visit-day"><option value="">Select a day</option>${e.days.length?e.days.map(d=>`<option value="${d.date}">${esc(d.label)}</option>`).join(''):'<option value="day-1">Day 1 - date to be confirmed</option><option value="day-2">Day 2 - date to be confirmed</option>'}</select></div></fieldset>${e.courseDates.length?`<fieldset class="ticket-fieldset"><legend>The financial course <span>Three separate 3-hour sessions</span></legend><p>General expo seminars are included with an expo pass. This financial course is separately ticketed and is <strong>not included</strong> in the $100 all-access pass.</p><div class="course-grid">${D.courses.map(c=>`<label class="course-card"><input type="checkbox" name="course" value="${c.id}"><span><strong>${esc(c.name)}</strong><small>${date(e.courseDates[c.dayIndex])} / 3 hours</small></span><b>${price(c.price)}</b></label>`).join('')}</div><label class="bundle-card"><input type="checkbox" data-course-bundle><span><strong>All three sessions</strong><small>9 hours across three days / save ${price(D.courses.reduce((s,c)=>s+c.price,0)-D.courseBundlePrice)} versus separate sessions</small></span><b>${price(D.courseBundlePrice)}</b></label><p class="small">Course session times and whether a course ticket includes expo admission are pending confirmation. Do not assume expo or networking access from a course purchase.</p></fieldset>`:'<div class="notice"><strong>Vegas extras are not yet on sale.</strong><p>All-access benefits and financial-course scheduling have not been confirmed for Las Vegas.</p></div>'}</div><aside class="selection-summary"><p class="eyebrow">Your selection</p><h3>Plan your visit.</h3><ul data-selection-lines><li>Choose a pass or course to see the estimate.</li></ul><div class="estimate"><span>Ticket subtotal</span><strong data-ticket-total>$0</strong></div><p class="small">USD. Taxes, fees and refund terms are not yet configured. No seats are reserved.</p><p data-ticket-message role="status">Select an option to review.</p><button type="button" class="button button-dark" disabled>Checkout not connected</button>${link('contact.html','Ask about passes '+arrow)}<p class="small">Exhibiting? ${link('exhibit.html#inquire','Talk with our team.')}</p></aside></div></div></section>`;}
function shell(title,active,body){const nav=[['events.html','Events','events'],['attend.html','Attend','attend'],['education.html','Education','education'],['hosted-buyers.html','Hosted buyers','buyer'],['news.html','Stories','news'],['about.html','About','about']];return `<!doctype html>
<html lang="en" class="age-pending"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | CannaCon Preview</title><meta name="description" content="${esc(title)}. ${esc(D.brand.tagline)}. Development preview; no ticket checkout."><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#092e24"><meta name="referrer" content="strict-origin-when-cross-origin"><link rel="icon" href="${B}assets/brand/cannacon-hand.png" type="image/png"><link rel="stylesheet" href="${B}cannacon.css?v=20260922b"><script src="${B}runtime-data.js?v=20260922b" defer></script><script src="${B}cannacon.js?v=20260922b" defer></script></head>
<body data-page="${esc(active)}"><a class="skip-link" href="#main">Skip to content</a><div class="site-shell" id="site-shell"><div class="preview-bar"><div class="wrap"><span><b>WEBSITE PREVIEW</b> / CannaCon 2027</span><span>Inquiries prepare an email draft. Ticket checkout is not connected.</span></div></div><header class="site-header"><div class="wrap nav-shell"><a href="${B}index.html" class="brand" aria-label="CannaCon home">${logo()}</a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="primary-nav" data-menu-toggle>Menu <span aria-hidden="true">&#9776;</span></button><nav id="primary-nav" class="primary-nav" aria-label="Primary navigation">${nav.map(([p,t,id])=>link(p,t,'nav-link',id===active?'aria-current="page"':'')).join('')}${link('exhibit.html','Exhibit with us '+arrow,'button button-orange',active==='exhibit'?'aria-current="page"':'')}</nav></div></header><main id="main" tabindex="-1">${body}</main><footer class="site-footer"><div class="wrap"><div class="footer-top"><div class="footer-brand">${link('index.html',logo(),'brand')}<p>${esc(D.brand.tagline)}</p><div class="socials">${link(D.socials.linkedin,'LinkedIn '+arrow,'text-link light')}${link(D.socials.youtube,'YouTube '+arrow,'text-link light')}</div><p class="small">More social channels coming soon.</p></div><nav aria-label="Event links"><h2>Find your show</h2>${D.events.map(e=>link(e.code+'/',esc(e.city))).join('')}${link('schedule.html','Schedule')}${link('attend.html','Pass options')}</nav><nav aria-label="Participate"><h2>Be part of it</h2>${link('exhibit.html','Exhibit')}${link('sponsor.html','Sponsor')}${link('speak.html','Speak')}${link('hosted-buyers.html','Hosted buyers')}${link('contact.html','Contact')}</nav><nav aria-label="Resources"><h2>Keep exploring</h2>${link('news.html','Stories & guides')}${link('education.html','Financial education')}${link('decks.html','Sales decks')}${link('about.html','About CannaCon')}${link('privacy.html','Preview privacy')}</nav></div><div class="footer-bottom"><p>&copy; ${new Date().getFullYear()} CannaCon&trade;. For adults 21+. Development preview.</p><button type="button" class="plain-button" data-cookie-settings>Privacy choices</button><button type="button" class="plain-button" data-reset-age>Reset age acknowledgement</button></div></div></footer></div>
<dialog id="age-gate" class="age-dialog" aria-labelledby="age-title" aria-describedby="age-description"><div class="age-art" aria-hidden="true"><img src="${B}assets/brand/cannacon-hand.png" alt="" width="300" height="615"></div><div class="age-content">${logo()}<p class="eyebrow">Culture. Commerce. Community.</p><h2 id="age-title">Are you 21 or older?</h2><p id="age-description">CannaCon's website and events are intended for adults 21 and older.</p><div data-age-actions><button class="button button-orange" type="button" data-age-yes>Yes, enter CannaCon</button><button class="button button-quiet" type="button" data-age-no>No, I am under 21</button></div><div data-age-restricted hidden><p>You must be 21 or older to enter this site.</p><button type="button" class="plain-button" data-age-reconsider>I selected the wrong option</button></div><p class="small">We remember your acknowledgement for ${D.ageRememberDays} days in this browser when storage is available. No date of birth is collected.</p></div></dialog>
<section class="privacy-banner" data-privacy-banner aria-labelledby="privacy-banner-title" hidden><div><strong id="privacy-banner-title">Your visit. Your choices.</strong><p>We store your age acknowledgement and privacy choice. No analytics or advertising tags run in this preview. External video loads only when requested.</p></div><div class="privacy-actions"><button type="button" class="button button-dark" data-privacy-essential>Essential only</button><button type="button" class="button button-quiet" data-cookie-settings>Preferences</button></div></section>
<dialog class="preferences-dialog" id="privacy-dialog" aria-labelledby="preferences-title"><form method="dialog"><div class="dialog-header"><h2 id="preferences-title">Privacy preferences</h2><button class="icon-button" value="cancel" aria-label="Close privacy preferences">&times;</button></div><p>Essential storage remembers age acknowledgement and these choices. No analytics or advertising cookies are added by this preview.</p><label class="preference-line"><span><strong>Essential browser storage</strong><small>Age acknowledgement and preferences only.</small></span><input type="checkbox" checked disabled aria-label="Essential storage enabled"></label><label class="preference-line"><span><strong>Remember external video permission</strong><small>Allow YouTube to load when its section is opened. You can change this choice at any time.</small></span><input type="checkbox" data-external-preference></label><p class="small">YouTube operates under its own privacy terms. These settings are not a legal compliance certification.</p><button type="button" class="button button-dark" data-save-preferences>Save preferences</button></form></dialog>
<noscript><style>.age-pending .site-shell{visibility:hidden}#age-gate{display:none}</style><div class="noscript"><p class="noscript-title">CannaCon / 21+</p><p>Please enable JavaScript to acknowledge your age and enter this preview. No payment is collected here.</p></div></noscript></body></html>`;}
function home(){return `<section class="hero"><div class="hero-media media-frame">${img(D.media.heroImage,'CannaCon attendees and exhibitors on the show floor','hero-photo',true)}<video class="hero-video" data-hero-video muted loop playsinline preload="none" aria-hidden="true"></video></div><div class="hero-overlay"></div><div class="wrap hero-inner"><p class="eyebrow">Cannabis. Hemp. Everything around them.</p><h1><span class="hero-preline">Where Cannabis</span>Culture, Commerce,<br>and Community<br><span class="hero-lastline">Come Together</span></h1><p class="hero-subtitle">The people. The products. The ideas. One gathering for the whole cannabis and hemp ecosystem.</p><div class="button-row">${link('exhibit.html#inquire','Exhibit at CannaCon '+arrow,'button button-orange')}${link('#events','Explore 2027 events','button button-outline')}</div><div class="hero-bottom"><p>CannaCon presents <span>Infused Product Expo / Culture / Cannabis Commerce</span></p><button type="button" class="motion-toggle" data-hero-toggle aria-pressed="false">Play show footage <span aria-hidden="true">&#9654;</span></button></div></div><div class="wave-edge" aria-hidden="true"></div></section>
<section class="intro section"><div class="wrap intro-grid"><p class="eyebrow">More than a trade show</p><div><h2>The industry in one place.<br><span class="serif-accent">A community that moves it forward.</span></h2><p>From the first conversation to the next big idea, CannaCon brings culture and business onto the same floor. Discover products, meet buyers and creators, build partnerships, and make room for what comes next.</p></div></div></section>
<section class="section event-section" id="events"><div class="wrap">${sectionHead('Find your people / 2027','Meet us on the floor.','Three destinations. One CannaCon community.',link('events.html','Explore all events '+arrow))}${eventCards()}</div></section>
<section class="section dark"><div class="wrap">${sectionHead('CannaCon presents','One show. A wider world.','Product discovery, cannabis culture and the business ecosystem. Connected, not separate.')}${pavilions()}<div class="section-end">${link('exhibit.html','Explore exhibitor opportunities '+arrow,'button button-orange')}<p>Education and culture programming connect the experience across the floor.</p></div></div></section>
<section class="section"><div class="wrap"><div class="split-feature"><div class="media-frame portrait">${img(D.media.conversations,'A conversation at a previous CannaCon event')}</div><div><p class="eyebrow">Built for the right conversations</p><h2>Your next connection<br>starts here.</h2><p>Exhibiting means more than being seen. Bring your business into a gathering designed for product discovery, buyer conversations, practical education and the communities around cannabis.</p><div class="feature-list"><div><span>01</span><p><strong>Meet across the ecosystem.</strong><br>Operators, brands, buyers, creators and the services that support them.</p></div><div><span>02</span><p><strong>Make more of the show floor.</strong><br>Connect your booth with product, culture and educational experiences.</p></div><div><span>03</span><p><strong>Keep the conversation going.</strong><br>Explore content, programming and partnership opportunities.</p></div></div>${link('exhibit.html#inquire','Talk to us about exhibiting '+arrow,'button button-dark')}</div></div></div></section>
<section class="section soft"><div class="wrap">${sectionHead('Make it your CannaCon','Choose how you show up.')}<div class="path-grid">${[['Attend','Discover the floor, the culture and the ideas.','attend.html'],['Exhibit','Bring your brand into the conversation.','exhibit.html'],['Sponsor','Build a presence beyond the booth.','sponsor.html'],['Speak','Put practical knowledge on the program.','speak.html']].map(([t,c,p],i)=>`<a class="path-card" href="${B+p}"><span class="eyebrow">0${i+1}</span><h3>${t} ${arrow}</h3><p>${c}</p></a>`).join('')}</div></div></section>
<section class="section buyer-band"><div class="wrap buyer-grid"><div><p class="eyebrow">Infused Product Expo / Hosted buyers</p><h2>Less searching.<br>Better conversations.</h2><p>Tell us what you source, buy or distribute. Build a buyer profile around categories, priorities and the suppliers you want to meet.</p><div class="button-row">${link('hosted-buyers.html','Explore the buyer program '+arrow,'button button-orange')}${link(D.decks[2].file,'Read the buyer guide '+arrow,'button button-outline','target="_blank" rel="noopener" type="application/pdf"')}</div><p class="small">Applications, introductions and hosted benefits are subject to review. The reference buyer guide contains earlier branding and unresolved Vegas dates.</p></div><img class="buyer-hand" src="${B}assets/brand/cannacon-hand.png" alt="" width="300" height="615" loading="lazy"></div></section>
${videoBlock()}<section class="section"><div class="wrap">${sectionHead('Stories worth coming back for','Cannabis, beyond the convention.','Selected stories from the existing CannaCon editorial library.',link('news.html','Explore stories '+arrow))}${articles()}</div></section><section class="section soft"><div class="wrap">${story()}</div></section>${sponsors()}${newsletter()}${cta()}`;}
function eventPage(e){return pageHead('CannaCon presents / '+esc(e.region),esc(e.name),esc(e.intro),link('exhibit.html#inquire','Exhibit here '+arrow,'button button-orange')+link('#tickets','Explore passes','button button-outline'))+`<section class="event-facts"><div class="wrap facts-grid"><div><span>Expo dates</span><strong>${esc(e.datesLabel)}</strong></div><div><span>Venue</span><strong>${esc(e.venue)}</strong>${e.address?`<small>${esc(e.address)}</small>`:''}</div><div><span>${e.preDate?'Pre-show day':'Program status'}</span><strong>${e.preDate?esc(e.preLabel)+', 2027':'Dates & hours pending'}</strong></div><div>${link(e.floorPlan,'Open floor plan '+arrow,'button button-dark')}</div></div></section>${e.dateStatus!=='confirmed'?'<div class="wrap"><div class="notice"><strong>Exact Vegas dates require confirmation.</strong><p>The supplied buyer guide lists May 14-15; the legacy site lists May 13-14. This preview intentionally displays May 2027 rather than choosing an unconfirmed date.</p></div></div>':''}${program(e)}<section class="section dark"><div class="wrap">${sectionHead('Across the floor','The CannaCon experience.')}${pavilions()}</div></section>${tickets(e)}<section class="section soft"><div class="wrap"><div class="info-grid"><article><h2>Travel & hotels</h2><p>Hotel blocks and detailed travel information will be added when approved. No booking offer is implied by this preview.</p>${link('contact.html','Ask the team '+arrow)}</article><article><h2>Exhibitor resources</h2><p>Review the sales deck and explore the floor plan. Service kits and decorator instructions will be linked after the provider is confirmed.</p>${link('decks.html','Open the sales library '+arrow)}</article></div></div></section>${cta()}`;}
const pages=[
 ['index.html','Where culture, commerce and community come together','home',home],
 ['events.html','2027 events','events',()=>pageHead('CannaCon 2027','Find your next connection.','Explore the CannaCon event portfolio. Every show brings the infused ecosystem, cannabis commerce and culture into one gathering.')+`<section class="section"><div class="wrap">${eventCards()}</div></section><section class="section dark"><div class="wrap">${sectionHead('One governing brand','CannaCon presents.')}${pavilions()}</div></section>`+cta()],
 ['attend.html','Attend CannaCon','attend',()=>pageHead('For the cannabis community','Come curious.<br>Leave connected.','Explore products, conversations, culture and education. General seminars are included with your expo pass.',link('events.html','Choose a show '+arrow,'button button-orange'))+`<section class="section"><div class="wrap">${sectionHead('Choose your destination','Make a plan for 2027.')}${eventCards()}<div class="notice"><strong>Ticket preview, not live checkout.</strong><p>Regional expo passes are $40 for one day or $80 for two days. A $100 all-access pass includes both expo days and pre-show networking. The financial course is separate. Vegas benefits remain under confirmation.</p></div></div></section><section class="section dark"><div class="wrap">${sectionHead('Discover the whole floor','Culture meets commerce.')}${pavilions()}</div></section>`+newsletter()],
 ['exhibit.html','Exhibit with CannaCon','exhibit',()=>pageHead('For the people building the industry','Bring your business.<br>Meet your market.','Products, equipment, services, brands and ideas. Find your place in a CannaCon gathering built for the full cannabis and hemp ecosystem.',link('#inquire','Request exhibitor information '+arrow,'button button-orange')+link('#sales-decks','Read the sales decks','button button-outline'))+`<section class="section" id="sales-decks"><div class="wrap">${sectionHead('Start with the opportunity','More ways to connect.')}${decks()}<p class="small">These are the supplied reference PDFs, unchanged. Some branding, dates and links predate the current website specification.</p></div></section><section class="section dark"><div class="wrap">${sectionHead('CannaCon presents','Find your place on the floor.')}${pavilions()}</div></section>`+formBlock('exhibitor')+cta()],
 ['sponsor.html','Sponsorship & partnerships','sponsor',()=>pageHead('Beyond the booth','Build a presence<br>people remember.','Explore event, pavilion, programming and content opportunities. Sponsorship is a conversation about fit, not a promise of generic impressions.',link('#inquire','Start a sponsorship conversation '+arrow,'button button-orange'))+`<section class="section"><div class="wrap"><div class="path-grid">${[['Pavilions','Bring your brand alongside a relevant part of the ecosystem.'],['Experiences','Explore product discovery, culture and on-floor activations.'],['Education','Support practical knowledge and meaningful conversations.'],['Content','Discuss editorial, interview and community opportunities.']].map(([t,c])=>`<article class="path-card"><h2>${t}</h2><p>${c}</p></article>`).join('')}</div><div class="notice">No sponsor roster, pricing, exclusivity or guaranteed benefit is published in this preview.</div></div></section>`+formBlock('sponsor')+sponsors()],
 ['speakers.html','Speakers & programming','speakers',()=>pageHead('Knowledge that moves the industry','Better questions.<br>Stronger conversations.','We are building the 2027 speaker and cultural program. Confirmed speakers will be published here; no placeholder names represent accepted participants.',link('speak.html','Propose a session '+arrow,'button button-orange')+link('education.html','Explore financial education','button button-outline'))+`<section class="section"><div class="wrap">${sectionHead('Programming in development','Practical expertise. Broader perspectives.')}<div class="info-grid"><article><h3>Business & operations</h3><p>Finance, retail, cultivation, manufacturing, technology and the work of building a better business.</p></article><article><h3>Culture & community</h3><p>Creators, glass, product experiences and the people shaping cannabis and hemp culture.</p></article></div></div></section>`+cta()],
 ['speak.html','Speaker inquiries','speakers',()=>pageHead('Bring something useful to the room','Share what you know.','Propose a session, workshop, panel or culture program. Tell us who it serves and what participants will take away.')+formBlock('speaker')],
 ['schedule.html','Program & schedule','events',()=>pageHead('CannaCon 2027','Make time for more.','Regional shows include a pre-show day followed by two expo days. Vegas uses a separate program, still being finalized.')+D.events.map(e=>`<div class="wrap program-city"><h2>${esc(e.name)}</h2>${link(e.code+'/','Show details '+arrow)}</div>`+program(e,'program-'+e.code)).join('')],
 ['news.html','Stories & editorial','news',()=>pageHead('From the CannaCon library','The conversation<br>does not stop here.','Explore existing CannaCon guides and stories. Links open the original editorial pages while the new library is being prepared.')+`<section class="section"><div class="wrap">${articles(true)}<p class="small">Articles retain their original publication context. They are not being represented as newly verified medical, legal or regulatory guidance.</p></div></section>`+newsletter()],
 ['about.html','About CannaCon','about',()=>pageHead('Culture. Commerce. Community.','If you\'re in Cannabis,<br>you\'re at CannaCon.','A gathering for the cannabis and hemp ecosystem: the people who create it, the businesses that build it, and the communities that move it forward.')+`<section class="section"><div class="wrap">${story()}</div></section><section class="section dark"><div class="wrap">${sectionHead('Our next chapter','More than a B2B floor.')}<p class="lead">CannaCon presents the Infused Product Expo, the Culture Pavilion and the Cannabis Commerce Pavilion, supported by practical education and cultural programming.</p>${pavilions()}</div></section>`+cta()],
 ['contact.html','Contact the CannaCon team','contact',()=>pageHead('Talk to the team','Start a conversation.','Choose the path that fits your inquiry. For now, all four email-draft workflows are addressed to '+esc(D.brand.contactEmail)+'.')+`<section class="section"><div class="wrap"><div class="path-grid">${[['Exhibit','exhibit.html#inquire'],['Sponsor','sponsor.html#inquire'],['Speak','speak.html#inquire'],['Hosted buyers','hosted-buyers.html#inquire']].map(([t,p])=>`<a href="${B+p}" class="path-card"><h2>${t} ${arrow}</h2><p>Open the dedicated inquiry.</p></a>`).join('')}</div><div class="notice"><h2>Something else?</h2>${link('mailto:'+D.brand.contactEmail+'?subject=CannaCon%20%7C%20General%20Inquiry',esc(D.brand.contactEmail),'text-link')}<p>For general questions, media inquiries or a topic not covered above.</p></div></div></section>`],
 ['hosted-buyers.html','Hosted buyers & one-to-one meetings','buyer',()=>pageHead('CannaCon presents / Infused Product Expo','Source smarter.<br>Meet with purpose.','Build a profile around what you actually want to source, buy or distribute. Our team uses that information to review fit and shape useful introductions.',link('#inquire','Build your buyer profile '+arrow,'button button-orange')+link(D.decks[2].file,'Open the buyer guide '+arrow,'button button-outline','target="_blank" rel="noopener" type="application/pdf"'))+`<section class="section"><div class="wrap">${sectionHead('The hosted buyer process','Less wasted time. Better supplier discovery.')}<div class="path-grid">${[['Build your profile','Tell us what you source, buy, distribute or want to add.'],['Select priorities','Share categories, target products and introductions.'],['Get reviewed & matched','The team reviews eligibility and relevant supplier fit.'],['Meet one-to-one','Use the conversation to evaluate fit and next steps.']].map(([t,p],i)=>`<article class="path-card"><p class="eyebrow">0${i+1}</p><h3>${t}</h3><p>${p}</p></article>`).join('')}</div><div class="notice"><strong>Who this is for</strong><p>Retail and dispensary buyers; distributors and wholesalers; convenience and specialty retail; multi-location and MSO teams; beverage and category managers; purchasing executives.</p><p>Submitting does not guarantee approval, meetings, admission, travel or accommodation. Product availability is subject to each event\'s rules.</p></div></div></section>`+formBlock('buyer')],
 ['education.html','Financial education','education',()=>pageHead('Applied business education','Turn information<br>into better decisions.','Three separate three-hour financial course sessions, offered across the pre-show day and the two expo days in Virginia Beach and St. Paul. Vegas scheduling remains to be confirmed.',link('events.html','Choose a show '+arrow,'button button-orange'))+`<section class="section"><div class="wrap">${sectionHead('The financial course','Learn one session. Or take all three.')}<div class="course-summary-grid">${D.courses.map(c=>`<article class="program-card"><p class="eyebrow">3-hour session</p><h2>${esc(c.name)}</h2><strong class="course-price">${price(c.price)}</strong><p>Detailed session syllabus and start time will be published separately.</p></article>`).join('')}<article class="program-card course-bundle-summary"><p class="eyebrow">The complete pathway</p><h2>All three</h2><strong class="course-price">${price(D.courseBundlePrice)}</strong><p>9 hours across three days. Save ${price(D.courses.reduce((s,c)=>s+c.price,0)-D.courseBundlePrice)} compared with separate sessions.</p></article></div><div class="notice"><strong>Separate from general seminars.</strong><p>General seminars are included with expo admission. The financial course is separately priced, including for holders of an all-access pass. Any expo admission bundled with course tickets requires confirmation.</p></div><div class="button-row">${link('VA27/#tickets','Virginia Beach course options '+arrow,'button button-dark')}${link('MN27/#tickets','St. Paul course options '+arrow,'button button-quiet')}</div></div></section>`],
 ['decks.html','Sales decks & buyer guide','exhibit',()=>pageHead('Reference library','Explore the opportunity.','Open the CannaCon sales deck, the Las Vegas deck and the hosted buyer guide in your browser. These are the original supplied PDFs, not revised documents.')+`<section class="section"><div class="wrap">${decks([0,1,2])}<div class="notice"><strong>Reference document notice.</strong><p>The documents may contain earlier branding, event dates, program concepts and links to the old website. The current website instructions govern this preview. Vegas dates remain explicitly unresolved.</p></div></div></section>`],
 ['privacy.html','Preview privacy & storage','privacy',()=>pageHead('Development preview','Privacy, without the mystery.','This is a practical disclosure of what this test site does. A final production privacy notice requires owner review before launch.')+`<section class="section"><div class="wrap prose"><h2>Essential browser storage</h2><p>We use a browser storage entry and a first-party cookie to remember a 21+ acknowledgement for ${D.ageRememberDays} days. The cookie is scoped to this CannaCon folder. This is an acknowledgement, not identity or age verification. Clearing storage, using a different browser, expiry or private browsing may cause the question to reappear.</p><h2>No analytics in this preview</h2><p>No GA4, advertising pixels or optional analytics scripts are installed by these pages. The hosting provider may maintain its own operational logs.</p><h2>External media and email inquiries</h2><p>Approved photos and optional video are currently served by CannaCon.org. YouTube loads only when requested or when you have saved external-media permission. Inquiry pages prepare email drafts locally. No inquiry data is sent to a server by this preview. When you open a draft or send a message, your email provider handles that information. Copy and save controls provide an alternative to an installed email app.</p><p>Newsletter signup is a non-submitting prototype. Ticket selections are calculated in the browser; no checkout or card fields are connected and no ticket is issued.</p><h2>Public preview</h2><p>This preview and its linked PDFs are publicly reachable. Search-engine instructions are not authentication. Do not upload private customer data, credentials, confidential contracts or unapproved documents.</p><h2>Contact</h2><p>${link('mailto:'+D.brand.contactEmail,esc(D.brand.contactEmail))}</p><button type="button" class="button button-dark" data-cookie-settings>Change privacy preferences</button></div></section>`]
];
function write(file,title,active,render){B=file.includes('/')?'../':'';const target=path.join(ROOT,file);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,shell(title,active,render()));}
for(const [file,title,active,render]of pages)write(file,title,active,render);
for(const e of D.events)write(e.code+'/index.html',e.name,'events',()=>eventPage(e));
// Only runtime-required public configuration. Never put secret keys or sponsor payment amounts here.
const runtime={ageRememberDays:D.ageRememberDays,privacyRememberDays:D.privacyRememberDays,media:D.media,forms:Object.fromEntries(Object.entries(D.forms).map(([key,f])=>[key,{title:f.title,subject:f.subject,recipient:D.brand.contactEmail,mode:'email-draft'}])),tickets:D.tickets,courses:D.courses,courseBundlePrice:D.courseBundlePrice,events:D.events.map(({code,days,preDate,courseDates,checkoutUrl})=>({code,days,preDate,courseDates,checkoutUrl}))};
fs.writeFileSync(path.join(ROOT,'runtime-data.js'),'// Generated by build.mjs from content/site.json.\nwindow.CANNACON_CONFIG = '+JSON.stringify(runtime,null,2)+';\n');
console.log(`Built ${pages.length+D.events.length} pages inside ${ROOT}`);
